class Solution {
    string a,b;
    set<tuple<int,int,int>>bad;
    bool dfs(int i,int j,int diff){
        if(i==(int)a.size()&&j==(int)b.size())return diff==0;
        auto state=make_tuple(i,j,diff);
        if(bad.count(state))return false;
        if(i<(int)a.size()&&isdigit(a[i])){
            int x=0;for(int k=i;k<(int)a.size()&&k<i+3&&isdigit(a[k]);++k){
                x=x*10+a[k]-'0';if(dfs(k+1,j,diff+x))return true;
            }
        }
        if(j<(int)b.size()&&isdigit(b[j])){
            int x=0;for(int k=j;k<(int)b.size()&&k<j+3&&isdigit(b[k]);++k){
                x=x*10+b[k]-'0';if(dfs(i,k+1,diff-x))return true;
            }
        }
        if(diff>0&&j<(int)b.size()&&isalpha(b[j])&&dfs(i,j+1,diff-1))return true;
        if(diff<0&&i<(int)a.size()&&isalpha(a[i])&&dfs(i+1,j,diff+1))return true;
        if(diff==0&&i<(int)a.size()&&j<(int)b.size()&&
           isalpha(a[i])&&isalpha(b[j])&&a[i]==b[j]&&dfs(i+1,j+1,0))return true;
        bad.insert(state);return false;
    }
public:
    bool possiblyEquals(string s1,string s2){a=s1;b=s2;bad.clear();return dfs(0,0,0);}
};
